package com.prem.order; import org.springframework.web.bind.annotation.*; import reactor.core.publisher.Mono; @RestController @RequestMapping("/orders") public class OrderController {private final ProductClient client;public OrderController(ProductClient c){client=c;}@GetMapping("/{orderId}") public Mono<OrderResponse> get(@PathVariable Long orderId,@RequestParam(defaultValue="1") Long productId){return client.getProduct(productId).map(p->new OrderResponse(orderId,p.id(),p.name(),p.price(),p.name().startsWith("Fallback")));}@GetMapping("/admin/report") public String report(){return "ADMIN-only order report";}record OrderResponse(Long orderId,Long productId,String productName,double price,boolean fallback){} }
